/* GENERATED by gen_hcon_augmented.py -- models are generated.
   SAT_PRODUCT_DISTRIBUTION_RULES
   *** UNRATIFIED. This payload is a BUILD-SIDE PROPOSAL from the map's
   augmentation blocks and has NOT been ratified by the modeller. Attributes here
   are not declared on this satellite in data_7.js. Do not treat it as part of the
   ratified vault. ***
   anchor      : HUB_PRODUCT   (kind: hub, origin: map.anchor)
   track       : unratified
   history     : SCD2
   feeders     : 1 emitted of 1 (one per source view AND run)
   runs        : 1 -- opus_health_v2
   payload     : 8 attribute(s), NULL-PADDED TO THE SATELLITE
   grain       : ONE ROW PER HUB_PRODUCT_HK
   hashdiff    : SAT_PRODUCT_DISTRIBUTION_RULES_HASHDIFF (builder decision BD1), GUARDED against an all-null input (s5.5):
                 without the guard every all-null row hashes to ONE value and the
                 satellite collapses to one row, which looks like change detection.
*/

with feeders as (
    select
        md5(upper('HUB_PRODUCT|' || (HUB_PRODUCT_BK__SCHEME_CODE_PLAN_ID))) as HUB_PRODUCT_HK
        , IMD_VALIDATE as INTERMEDIARY_CODE_VALIDATION_REQUIRED_INDICATOR
        , GENERIC_SMS_IMDS as GENERIC_SMS_INTERMEDIARY_CODE_SET
        , SPECIFIC_SMS_IMDS as PLAN_SPECIFIC_SMS_INTERMEDIARY_CODE_SET
        , SUB_IMD_CODE as AUTHORISED_SUB_INTERMEDIARY_CODE_SET
        , SUB_IMD_VALIDATE as SUB_INTERMEDIARY_CODE_VALIDATION_REQUIRED_INDICATOR
        , NB_BLOCKED_YN as NEW_BUSINESS_BLOCKED_INDICATOR
        , IMD_BACKDATE_VALYN as INTERMEDIARY_BACKDATING_VALIDATION_REQUIRED_INDICATOR
        , BACKDATE_IMD_CODE as BACKDATING_AUTHORISED_INTERMEDIARY_CODE_SET
        , 'BJAZ_CTNGY_SCHEME_PLANS' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_ctngy_scheme_plans') }}
    where (nullif('SCHEMEPLAN:' || nullif(trim(SCHEME_CODE),'') || '|' || nullif(trim(PLAN_ID),''), 'SCHEMEPLAN:|')) is not null
),

resolved as (
    select
        HUB_PRODUCT_HK,
        max(case when SOURCE_RUN = 'opus_health_v2' then INTERMEDIARY_CODE_VALIDATION_REQUIRED_INDICATOR end) as INTERMEDIARY_CODE_VALIDATION_REQUIRED_INDICATOR,
        max(case when SOURCE_RUN = 'opus_health_v2' then GENERIC_SMS_INTERMEDIARY_CODE_SET end) as GENERIC_SMS_INTERMEDIARY_CODE_SET,
        max(case when SOURCE_RUN = 'opus_health_v2' then PLAN_SPECIFIC_SMS_INTERMEDIARY_CODE_SET end) as PLAN_SPECIFIC_SMS_INTERMEDIARY_CODE_SET,
        max(case when SOURCE_RUN = 'opus_health_v2' then AUTHORISED_SUB_INTERMEDIARY_CODE_SET end) as AUTHORISED_SUB_INTERMEDIARY_CODE_SET,
        max(case when SOURCE_RUN = 'opus_health_v2' then SUB_INTERMEDIARY_CODE_VALIDATION_REQUIRED_INDICATOR end) as SUB_INTERMEDIARY_CODE_VALIDATION_REQUIRED_INDICATOR,
        max(case when SOURCE_RUN = 'opus_health_v2' then NEW_BUSINESS_BLOCKED_INDICATOR end) as NEW_BUSINESS_BLOCKED_INDICATOR,
        max(case when SOURCE_RUN = 'opus_health_v2' then INTERMEDIARY_BACKDATING_VALIDATION_REQUIRED_INDICATOR end) as INTERMEDIARY_BACKDATING_VALIDATION_REQUIRED_INDICATOR,
        max(case when SOURCE_RUN = 'opus_health_v2' then BACKDATING_AUTHORISED_INTERMEDIARY_CODE_SET end) as BACKDATING_AUTHORISED_INTERMEDIARY_CODE_SET,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_PRODUCT_HK
),

hashed as (
    select
        *,
        case when INTERMEDIARY_CODE_VALIDATION_REQUIRED_INDICATOR is not null or GENERIC_SMS_INTERMEDIARY_CODE_SET is not null or PLAN_SPECIFIC_SMS_INTERMEDIARY_CODE_SET is not null or AUTHORISED_SUB_INTERMEDIARY_CODE_SET is not null or SUB_INTERMEDIARY_CODE_VALIDATION_REQUIRED_INDICATOR is not null or NEW_BUSINESS_BLOCKED_INDICATOR is not null or INTERMEDIARY_BACKDATING_VALIDATION_REQUIRED_INDICATOR is not null or BACKDATING_AUTHORISED_INTERMEDIARY_CODE_SET is not null
                     then md5(upper(coalesce(cast(INTERMEDIARY_CODE_VALIDATION_REQUIRED_INDICATOR as varchar), '') || '|' || coalesce(cast(GENERIC_SMS_INTERMEDIARY_CODE_SET as varchar), '') || '|' || coalesce(cast(PLAN_SPECIFIC_SMS_INTERMEDIARY_CODE_SET as varchar), '') || '|' || coalesce(cast(AUTHORISED_SUB_INTERMEDIARY_CODE_SET as varchar), '') || '|' || coalesce(cast(SUB_INTERMEDIARY_CODE_VALIDATION_REQUIRED_INDICATOR as varchar), '') || '|' || coalesce(cast(NEW_BUSINESS_BLOCKED_INDICATOR as varchar), '') || '|' || coalesce(cast(INTERMEDIARY_BACKDATING_VALIDATION_REQUIRED_INDICATOR as varchar), '') || '|' || coalesce(cast(BACKDATING_AUTHORISED_INTERMEDIARY_CODE_SET as varchar), '')))
                end as SAT_PRODUCT_DISTRIBUTION_RULES_HASHDIFF
    from resolved
)

select * from hashed
where HUB_PRODUCT_HK is not null
  and SAT_PRODUCT_DISTRIBUTION_RULES_HASHDIFF is not null
